function ClientProfile({ client, state, onClose }: { client: Client | null; state: AppState; onClose: () => void }) {
  if (!client) return null;
  const cols = state.collections.filter(c => c.clientId === client.id);
  const paid = cols.filter(c => ["Paga", "Baixada"].includes(c.status)).reduce((a, c) => a + c.amount, 0);
  const openAmount = cols.filter(c => !["Paga", "Baixada", "Arquivada"].includes(c.status)).reduce((a, c) => a + c.amount, 0);
  const guidance = collectionGuidance(state, client.id);
  const policy = state.settings.colorRules.find(rule => rule.id === client.colorRuleId);
  const group = state.settings.customerGroups.find(item => item.id === client.groupId);
  return <Sheet open onOpenChange={o => !o && onClose()}><SheetContent className="profile-sheet"><SheetHeader><SheetTitle>{client.name}</SheetTitle><SheetDescription>{client.company} · {client.document}</SheetDescription></SheetHeader><div className="profile-score"><span className={`score-dot ${client.priority.toLowerCase()}`} /><div><small>Política de cobrança</small><strong>{policy?.name || client.priority}</strong></div><Status>{guidance.open} vencida(s)</Status></div><div className={`policy-guidance tone-${guidance.tone}`}><TriangleAlert /><span><strong>{guidance.label}</strong><small>{policy?.action}</small></span></div><div className="mini-metrics"><div><small>Total faturado</small><strong>{money.format(paid + openAmount)}</strong></div><div><small>Em aberto</small><strong>{money.format(openAmount)}</strong></div><div><small>Notas</small><strong>{state.emissions.filter(e => e.clientId === client.id && e.status === "Emitida").reduce((a, e) => a + e.invoiceNumbers.length, 0)}</strong></div><div><small>Pendências vencidas</small><strong>{guidance.open}</strong></div></div><Tabs defaultValue="dados"><TabsList><TabsTrigger value="dados">Dados</TabsTrigger><TabsTrigger value="faturas">Faturas</TabsTrigger><TabsTrigger value="cobrancas">Cobranças</TabsTrigger></TabsList><TabsContent value="dados" className="profile-data"><Info label="E-mail" value={client.email} /><Info label="WhatsApp" value={client.whatsapp} /><Info label="Fechamento" value={state.settings.closingRules.find(rule => rule.id === client.closingRuleId)?.name || client.closing} /><Info label="Vencimento" value={state.settings.dueRules.find(rule => rule.id === client.dueRuleId)?.name || client.dueRule} /><Info label="Grupo / pagador" value={group ? `${group.name} → ${group.payerName}` : "Sem grupo"} /><Info label="Verificar pedido" value={client.requiresOrderCheck ? "Sim" : "Não"} /><Info label="Pagamento" value={client.payment} /><Info label="Envio" value={client.sending} /><Info label="Emissor" value={client.issuer} /><Info label="Cobradores" value={client.collectors.join(", ")} /><Info label="Observações" value={client.notes || "Nenhuma"} /></TabsContent><TabsContent value="faturas" className="timeline">{state.emissions.filter(e => e.clientId === client.id).map(e => <div key={e.id}><i /><span><strong>{e.invoiceNumbers.length ? `NF ${e.invoiceNumbers.join(",")}` : "Programada"}</strong><small>{dateBR(e.scheduledDate)} · {money.format(e.amount)} · {e.orderCheck}</small></span><Status>{e.status}</Status></div>)}</TabsContent><TabsContent value="cobrancas" className="timeline">{cols.map(c => <div key={c.id}><i /><span><strong>NF {c.invoice}</strong><small>{dateBR(c.dueDate)} · {money.format(c.amount)}</small></span><Status>{c.status}</Status></div>)}</TabsContent></Tabs></SheetContent></Sheet>;
}

function Finance({ state, commit }: { state: AppState; commit: Commit }) {
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState("Todos");
  const [scope, setScope] = useState("Hoje");
  const [company, setCompany] = useState("Todas");
  const [dialog, setDialog] = useState<Emission | null>(null);
  const [manual, setManual] = useState(false);
  const [nfs, setNfs] = useState<string[]>([""]);
  const [due, setDue] = useState("");
  const [observation, setObservation] = useState("");
  const filtered = state.emissions.filter(e => {
    const client = state.clients.find(c => c.id === e.clientId);
    const inScope = scope === "Todas" || (scope === "Hoje" && e.scheduledDate === today) || (scope === "Atrasadas" && e.scheduledDate < today && e.status === "Pendente") || (scope === "Próximas" && e.scheduledDate > today);
    return inScope && (status === "Todos" || e.status === status) && (company === "Todas" || e.company === company) && (client?.name ?? "").toLowerCase().includes(search.toLowerCase());
  }).sort((a, b) => a.scheduledDate.localeCompare(b.scheduledDate));

  function openComplete(emission: Emission) {
    if (emission.orderCheck === "A verificar") return toast.error("Confirme se existe pedido ou marque Sem pedido");
    const client = state.clients.find(item => item.id === emission.clientId);
    const dueRule = state.settings.dueRules.find(rule => rule.id === client?.dueRuleId);
    setDialog(emission); setNfs(emission.invoiceNumbers.length ? emission.invoiceNumbers : [""]); setDue(calculateDueDate(emission.scheduledDate, dueRule)); setObservation(emission.observation);
  }

  function complete() {
    if (!dialog || nfs.some(n => !n.trim()) || !due) return toast.error("Informe NFs e vencimento");
    commit(`Concluiu emissão ${dialog.id}`, draft => {
      const emission = draft.emissions.find(item => item.id === dialog.id); if (!emission) return;
      const client = draft.clients.find(item => item.id === emission.clientId);
      const policy = draft.settings.colorRules.find(item => item.id === client?.colorRuleId);
      emission.status = "Emitida"; emission.invoiceNumbers = nfs.map(n => n.trim()); emission.dueDate = due; emission.observation = observation;
      emission.invoiceNumbers.forEach(invoice => draft.collections.unshift({ id: uid("cobranca"), clientId: emission.clientId, invoice, dueDate: due, amount: emission.amount / emission.invoiceNumbers.length, priority: client?.priority ?? "Verde", policyId: client?.colorRuleId ?? "color-green", status: "Pendente", responsible: client?.collectors[0] ?? "Natanael", nextContact: due + "T08:00", availableFrom: addDays(due, policy?.collectionDelayDays ?? 1), attempts: 0, history: [{ at: new Date().toISOString(), user: "Sistema", channel: "Sistema", summary: `Cobrança criada. No vencimento: lembrete. Disponível para cobrar em ${dateBR(addDays(due, policy?.collectionDelayDays ?? 1))}.` }] }));
    });
    setDialog(null); toast.success("Emissão concluída. Lembrete e cobrança programados.");
  }

  const todayPending = state.emissions.filter(e => e.scheduledDate === today && e.status === "Pendente").length;
  const overdue = state.emissions.filter(e => e.scheduledDate < today && e.status === "Pendente").length;
  const needsOrderCheck = state.emissions.filter(e => e.scheduledDate === today && e.status === "Pendente" && e.orderCheck === "A verificar").length;
  return <><PageTitle eyebrow="Módulo Financeiro" title="Contas a emitir" description="Agenda automática de fechamentos, notas de hoje, atrasadas e verificação de pedidos." actions={<><Button variant="outline" onClick={() => commit("Atualizou agenda automática", draft => Object.assign(draft, ensureFinancialSchedule(draft)))}><RefreshCw /> Atualizar agenda</Button><Button onClick={() => setManual(true)}><Plus /> Emissão manual</Button></>} />
    <div className="metrics-grid compact"><Metric label="Emitir hoje" value={todayPending} detail="visível sem abrir planilha" icon={CalendarDays} /><Metric label="Atrasadas" value={overdue} detail="datas de emissão vencidas" icon={Clock3} tone="red" /><Metric label="Verificar pedido" value={needsOrderCheck} detail="marcar Tem pedido ou Sem pedido" icon={Search} tone="blue" /><Metric label="Emitidas" value={state.emissions.filter(e => e.status === "Emitida").length} detail="histórico registrado" icon={CheckCircle2} tone="green" /></div>
    <Card><CardHeader><div className="finance-scope">{["Hoje", "Atrasadas", "Próximas", "Todas"].map(value => <Button size="sm" key={value} variant={scope === value ? "default" : "outline"} onClick={() => setScope(value)}>{value}{value === "Hoje" ? ` (${todayPending})` : value === "Atrasadas" ? ` (${overdue})` : ""}</Button>)}</div><div className="toolbar"><div className="searchbox"><Search /><Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Buscar cliente" /></div><NativeSelect value={company} onChange={e => setCompany(e.target.value)}><NativeSelectOption>Todas</NativeSelectOption>{state.settings.companies.map(item => <NativeSelectOption key={item.name}>{item.name}</NativeSelectOption>)}</NativeSelect><NativeSelect value={status} onChange={e => setStatus(e.target.value)}><NativeSelectOption>Todos</NativeSelectOption>{["Pendente", "Emitida", "Sem pedido", "Cancelada"].map(value => <NativeSelectOption key={value}>{value}</NativeSelectOption>)}</NativeSelect></div></CardHeader><CardContent className="table-shell"><Table><TableHeader><TableRow><TableHead>Emissão</TableHead><TableHead>Cliente</TableHead><TableHead>Regra</TableHead><TableHead>Pedido</TableHead><TableHead>Responsável</TableHead><TableHead>Vencimento</TableHead><TableHead>Status</TableHead><TableHead className="right">Ações</TableHead></TableRow></TableHeader><TableBody>{filtered.map(emission => { const client = state.clients.find(item => item.id === emission.clientId); const late = emission.scheduledDate < today && emission.status === "Pendente"; return <TableRow key={emission.id} className={late ? "late-row" : ""}><TableCell><strong>{dateBR(emission.scheduledDate)}</strong>{late && <small className="cell-note danger-text">{daysBetween(emission.scheduledDate, today)} dia(s) atrasada</small>}{emission.scheduledDate !== emission.originalDate && <small className="cell-note">Adiantada</small>}</TableCell><TableCell><strong>{client?.name}</strong><small className="cell-note">{emission.company.replace("Indústria de Pães ", "")}</small></TableCell><TableCell>{emission.category}</TableCell><TableCell><Status>{emission.orderCheck}</Status></TableCell><TableCell>{emission.responsible}</TableCell><TableCell>{dateBR(emission.dueDate)}</TableCell><TableCell><Status>{emission.status}</Status></TableCell><TableCell className="right">{emission.status === "Pendente" && <>{emission.orderCheck === "A verificar" && <Button variant="outline" size="sm" onClick={() => commit(`Confirmou pedido ${emission.id}`, draft => { const item = draft.emissions.find(current => current.id === emission.id); if (item) item.orderCheck = "Tem pedido"; })}><Check /> Tem pedido</Button>}<Button variant="outline" size="sm" disabled={emission.orderCheck === "A verificar"} onClick={() => openComplete(emission)}><ReceiptText /> Emitir NF</Button>{emission.orderCheck !== "Não necessário" && <Button variant="ghost" size="sm" onClick={() => commit(`Marcou ${emission.id} sem pedido`, draft => { const item = draft.emissions.find(current => current.id === emission.id); if (item) { item.status = "Sem pedido"; item.orderCheck = "Sem pedido"; item.observation = "Sem pedido confirmado; não gerou cobrança."; } })}>Sem pedido</Button>}</>}</TableCell></TableRow>; })}</TableBody></Table></CardContent></Card>
    <Dialog open={Boolean(dialog)} onOpenChange={open => !open && setDialog(null)}><DialogContent>{dialog && <><DialogHeader><DialogTitle>Concluir emissão</DialogTitle><DialogDescription>{state.clients.find(c => c.id === dialog.clientId)?.name} · {dateBR(dialog.scheduledDate)}</DialogDescription></DialogHeader><div className="stack"><Label>Número(s) da NF</Label>{nfs.map((nf, index) => <div className="inline" key={index}><Input value={nf} onChange={event => setNfs(nfs.map((item, current) => current === index ? event.target.value : item))} />{nfs.length > 1 && <Button variant="ghost" size="icon" onClick={() => setNfs(nfs.filter((_, current) => current !== index))}><X /></Button>}</div>)}<Button variant="outline" size="sm" onClick={() => setNfs([...nfs, ""])}><Plus /> Adicionar NF</Button><Field label="Vencimento calculado"><Input type="date" value={due} onChange={event => setDue(event.target.value)} /></Field><Field label="Observação"><Textarea value={observation} onChange={event => setObservation(event.target.value)} /></Field><div className="callout"><CircleDollarSign /><span>No vencimento, o cobrador recebe um lembrete. A cobrança entra na fila conforme a política do cliente.</span></div></div><DialogFooter><Button variant="outline" onClick={() => setDialog(null)}>Cancelar</Button><Button onClick={complete}>Concluir emissão</Button></DialogFooter></>}</DialogContent></Dialog><ManualEmission open={manual} onClose={() => setManual(false)} state={state} commit={commit} />
  </>;
}
function ManualEmission({ open, onClose, state, commit }: { open: boolean; onClose: () => void; state: AppState; commit: Commit }) { const [clientId, setClientId] = useState(state.clients[0]?.id ?? ""), [date, setDate] = useState(today), [amount, setAmount] = useState(0); function save() { const c = state.clients.find(x => x.id === clientId); if (!c) return; const closing = state.settings.closingRules.find(rule => rule.id === c.closingRuleId), dueRule = state.settings.dueRules.find(rule => rule.id === c.dueRuleId); commit(`Criou emissão manual para ${c.name}`, d => d.emissions.unshift({ id: uid("emissao"), clientId, scheduledDate: date, originalDate: date, company: c.company, category: "Emissão manual", priority: "Média", responsible: c.issuer, status: "Pendente", invoiceNumbers: [], dueDate: calculateDueDate(date, dueRule), observation: "Emissão manual; não altera o cronograma automático.", amount, orderCheck: c.requiresOrderCheck || closing?.requiresOrderCheck ? "A verificar" : "Não necessário", autoGenerated: false })); onClose(); toast.success("Emissão criada"); } return <Dialog open={open} onOpenChange={o => !o && onClose()}><DialogContent><DialogHeader><DialogTitle>Nova emissão manual</DialogTitle><DialogDescription>Não altera o cronograma futuro do cliente.</DialogDescription></DialogHeader><div className="stack"><Field label="Cliente"><NativeSelect value={clientId} onChange={e => setClientId(e.target.value)}>{state.clients.map(c => <NativeSelectOption value={c.id} key={c.id}>{c.name}</NativeSelectOption>)}</NativeSelect></Field><Field label="Data"><Input type="date" value={date} onChange={e => setDate(e.target.value)} /></Field><Field label="Valor estimado"><Input type="number" value={amount} onChange={e => setAmount(Number(e.target.value))} /></Field></div><DialogFooter><Button variant="outline" onClick={onClose}>Cancelar</Button><Button onClick={save}>Criar</Button></DialogFooter></DialogContent></Dialog>; }

function Collections({ state, commit, user, token }: { state: AppState; commit: Commit; user: string; token: string }) {
  const [search, setSearch] = useState(""), [filter, setFilter] = useState("Todos"), [scope, setScope] = useState("Cobrar hoje"), [selected, setSelected] = useState<string[]>([]), [acting, setActing] = useState<Collection | null>(null), [mode, setMode] = useState<"contact" | "payment" | "reschedule" | "cancel">("contact"), [summary, setSummary] = useState(""), [nextContact, setNextContact] = useState(""), [proof, setProof] = useState<File | null>(null), [manual, setManual] = useState(false), [manualClient, setManualClient] = useState(state.clients[0]?.id || ""), [manualInvoice, setManualInvoice] = useState(""), [manualDue, setManualDue] = useState(today), [manualAmount, setManualAmount] = useState(0);
  const active = (item: Collection) => !["Paga", "Baixada", "Arquivada"].includes(item.status);
  const remindersToday = state.collections.filter(item => active(item) && item.dueDate === today);
  const chargeableToday = state.collections.filter(item => active(item) && item.availableFrom <= today);
  const filtered = state.collections.filter(item => { const clientName = state.clients.find(client => client.id === item.clientId)?.name || ""; const inScope = scope === "Todas" || (scope === "Vencem hoje" && item.dueDate === today && active(item)) || (scope === "Cobrar hoje" && item.availableFrom <= today && active(item)); return inScope && (filter === "Todos" || item.status === filter || item.priority === filter) && clientName.toLowerCase().includes(search.toLowerCase()); });
  const counts = (statusName: Collection["status"]) => state.collections.filter(item => item.status === statusName).length;
  function start(item: Collection, m: typeof mode) { setActing(item); setMode(m); setSummary(""); setNextContact(item.nextContact.slice(0, 16)); setProof(null); }
  async function apply() {
    if (!acting) return;
    const chosenProof = proof ?? document.querySelector<HTMLInputElement>('input[accept=".pdf,.jpg,.jpeg,.png"]')?.files?.[0] ?? null;
    if (mode === "contact" && !summary.trim()) return toast.error("Resumo obrigatório");
    if (mode === "payment" && !chosenProof) return toast.error("Anexe o comprovante de pagamento");
    if (mode === "payment" && chosenProof && chosenProof.size > 5 * 1024 * 1024) return toast.error("O comprovante deve ter no máximo 5 MB");
    if (mode === "payment" && chosenProof && token !== "local-demo") {
      const form = new FormData(); form.append("file", chosenProof);
      const uploaded = await fetch("/api/files", { method: "POST", headers: { authorization: `Bearer ${token}` }, body: form });
      if (!uploaded.ok) return toast.error("Não foi possível salvar o comprovante");
    }
    commit(`Atualizou cobrança NF ${acting.invoice}`, d => {
      const x = d.collections.find(c => c.id === acting.id); if (!x) return;
      if (mode === "contact") { x.status = "Em andamento"; x.attempts++; x.history.unshift({ at: new Date().toISOString(), user, channel: "WhatsApp", summary }); }
      if (mode === "payment") { x.status = "Paga"; x.history.unshift({ at: new Date().toISOString(), user, channel: "Sistema", summary: `${summary || "Pagamento registrado; aguardando baixa."} Comprovante: ${chosenProof?.name}.` }); }
      if (mode === "reschedule") { x.status = "Reagendada"; x.nextContact = nextContact; x.history.unshift({ at: new Date().toISOString(), user, channel: "Sistema", summary: summary || "Cobrança reagendada." }); }
      if (mode === "cancel") { x.status = "Cancelamento pendente"; x.history.unshift({ at: new Date().toISOString(), user, channel: "Sistema", summary: summary || "Não pagamento após cobrança imediata; fornecimento encaminhado para cancelamento." }); }
    });
    setActing(null); toast.success("Cobrança atualizada");
  }
  function createManual() { const client = state.clients.find(item => item.id === manualClient); if (!client || !manualInvoice.trim()) return toast.error("Informe cliente e NF"); const policy = state.settings.colorRules.find(item => item.id === client.colorRuleId); commit(`Criou cobrança manual NF ${manualInvoice}`, draft => draft.collections.unshift({ id: uid("cobranca"), clientId: client.id, invoice: manualInvoice.trim(), dueDate: manualDue, amount: manualAmount, priority: client.priority, policyId: client.colorRuleId, status: "Pendente", responsible: client.collectors[0] || "Natanael", nextContact: `${manualDue}T08:00`, availableFrom: addDays(manualDue, policy?.collectionDelayDays ?? 1), attempts: 0, history: [{ at: new Date().toISOString(), user, channel: "Sistema", summary: "Cobrança criada manualmente." }] })); setManual(false); setManualInvoice(""); toast.success("Cobrança criada"); }
  return <><PageTitle eyebrow="Ciclo financeiro" title="Cobranças" description="No vencimento há lembrete; a fila de cobrança começa depois, conforme a política escolhida para o cliente." actions={<Button onClick={() => setManual(true)}><Plus /> Nova cobrança</Button>} /><div className="policy-banner"><div className="green"><strong>Verde</strong><span>Várias pendências; cobrar normalmente; não cancelar entregas.</span></div><div className="yellow"><strong>Amarelo</strong><span>No máximo duas pendências em aberto.</span></div><div className="red"><strong>Vermelho</strong><span>Nenhuma pendência vencida; cobrar no dia seguinte e cancelar se não pagar.</span></div></div><div className="metrics-grid compact"><Metric label="Vencem hoje" value={remindersToday.length} detail="lembretes aos cobradores" icon={Bell} /><Metric label="Cobrar hoje" value={chargeableToday.length} detail="após o vencimento" icon={WalletCards} tone="red" /><Metric label="Em andamento" value={counts("Em andamento") + counts("Reagendada")} detail="inclui reagendadas" icon={RefreshCw} tone="blue" /><Metric label="Pagas" value={counts("Paga")} detail="aguardando baixa" icon={CheckCircle2} tone="green" /></div><Card><CardHeader><div className="finance-scope">{["Cobrar hoje", "Vencem hoje", "Todas"].map(value => <Button size="sm" key={value} variant={scope === value ? "default" : "outline"} onClick={() => setScope(value)}>{value}</Button>)}</div><div className="toolbar"><div className="searchbox"><Search /><Input placeholder="Buscar cliente" value={search} onChange={e => setSearch(e.target.value)} /></div><NativeSelect value={filter} onChange={e => setFilter(e.target.value)}><NativeSelectOption>Todos</NativeSelectOption>{["Pendente", "Em andamento", "Reagendada", "Paga", "Baixada", "Cancelamento pendente", "Vermelho", "Amarelo", "Verde"].map(x => <NativeSelectOption key={x}>{x}</NativeSelectOption>)}</NativeSelect>{selected.length > 0 && <div className="bulk"><strong>{selected.length} selecionadas</strong><Button size="sm" variant="outline" onClick={() => { commit("Arquivou cobranças em massa", d => d.collections.forEach(c => { if (selected.includes(c.id)) c.status = "Arquivada"; })); setSelected([]); }}><Archive /> Arquivar</Button></div>}</div></CardHeader><CardContent className="table-shell"><Table><TableHeader><TableRow><TableHead><Checkbox checked={filtered.length > 0 && selected.length === filtered.length} onCheckedChange={v => setSelected(v ? filtered.map(c => c.id) : [])} /></TableHead><TableHead>Cliente / NF</TableHead><TableHead>Vencimento</TableHead><TableHead>Política e limite</TableHead><TableHead>Responsável</TableHead><TableHead>Status</TableHead><TableHead className="right">Registrar</TableHead></TableRow></TableHeader><TableBody>{filtered.map(item => { const guidance = collectionGuidance(state, item.clientId), client = state.clients.find(current => current.id === item.clientId), canCharge = item.availableFrom <= today, overdueDays = Math.max(0, daysBetween(item.dueDate, today)), canCancel = guidance.policy?.cancelAfterUnpaid && overdueDays >= (client?.cancellationDays || 1) && item.attempts > 0; return <TableRow key={item.id}><TableCell><Checkbox checked={selected.includes(item.id)} onCheckedChange={v => setSelected(v ? [...selected, item.id] : selected.filter(id => id !== item.id))} /></TableCell><TableCell><strong>{client?.name}</strong><small className="cell-note">NF {item.invoice} · {money.format(item.amount)}</small></TableCell><TableCell><strong>{dateBR(item.dueDate)}</strong><small className={`cell-note ${overdueDays ? "danger-text" : ""}`}>{item.dueDate === today ? "Vence hoje · lembrete" : overdueDays ? `${overdueDays} dia(s) de atraso` : `Cobrar a partir de ${dateBR(item.availableFrom)}`}</small></TableCell><TableCell><Status>{guidance.policy?.name || item.priority}</Status><small className="cell-note">{guidance.label}</small></TableCell><TableCell>{item.responsible}<small className="cell-note">{item.attempts} tentativa(s)</small></TableCell><TableCell><Status>{item.status}</Status></TableCell><TableCell className="right">{canCharge ? <Button size="sm" variant="outline" onClick={() => start(item, "contact")}>Cobrar</Button> : <Button size="sm" variant="outline" disabled><Bell /> Lembrete</Button>}<Button size="sm" variant="ghost" onClick={() => start(item, "payment")}><Check /> Pago</Button>{canCancel ? <Button size="sm" variant="ghost" onClick={() => start(item, "cancel")}><TriangleAlert /> Cancelar</Button> : <Button size="icon" variant="ghost" onClick={() => start(item, "reschedule")}><CalendarDays /></Button>}</TableCell></TableRow>; })}</TableBody></Table></CardContent></Card><Dialog open={Boolean(acting)} onOpenChange={o => !o && setActing(null)}><DialogContent>{acting && <><DialogHeader><DialogTitle>{{ contact: "Registrar cobrança", payment: "Registrar pagamento", reschedule: "Reagendar cobrança", cancel: "Encaminhar cancelamento" }[mode]}</DialogTitle><DialogDescription>{state.clients.find(c => c.id === acting.clientId)?.name} · NF {acting.invoice} · {money.format(acting.amount)}</DialogDescription></DialogHeader><div className="stack">{mode === "contact" && <Field label="Meio"><NativeSelect><NativeSelectOption>WhatsApp</NativeSelectOption><NativeSelectOption>E-mail</NativeSelectOption><NativeSelectOption>Telefone</NativeSelectOption><NativeSelectOption>Presencial</NativeSelectOption></NativeSelect></Field>}{mode === "payment" && <><Field label="Pagamento"><NativeSelect>{state.settings.paymentMethods.map(x => <NativeSelectOption key={x}>{x}</NativeSelectOption>)}</NativeSelect></Field><Field label="Comprovante"><Input type="file" accept=".pdf,.jpg,.jpeg,.png" onChange={e => setProof(e.target.files?.[0] || null)} /></Field></>}{mode === "reschedule" && <Field label="Próximo contato"><Input type="datetime-local" value={nextContact} onChange={e => setNextContact(e.target.value)} /></Field>}<Field label={mode === "contact" ? "Resumo (obrigatório)" : "Observações / justificativa"}><Textarea value={summary} onChange={e => setSummary(e.target.value)} /></Field>{mode === "cancel" && <div className="callout danger"><TriangleAlert /><span>O fornecimento será encaminhado para cancelamento por falta de pagamento.</span></div>}</div><DialogFooter><Button variant="outline" onClick={() => setActing(null)}>Cancelar</Button><Button onClick={apply}>Confirmar</Button></DialogFooter></>}</DialogContent></Dialog><Dialog open={manual} onOpenChange={setManual}><DialogContent><DialogHeader><DialogTitle>Nova cobrança manual</DialogTitle><DialogDescription>Use para cobranças que não vieram de uma emissão registrada.</DialogDescription></DialogHeader><div className="stack"><Field label="Cliente"><NativeSelect value={manualClient} onChange={e => setManualClient(e.target.value)}>{state.clients.map(client => <NativeSelectOption value={client.id} key={client.id}>{client.name}</NativeSelectOption>)}</NativeSelect></Field><Field label="NF / referência"><Input value={manualInvoice} onChange={e => setManualInvoice(e.target.value)} /></Field><Field label="Vencimento"><Input type="date" value={manualDue} onChange={e => setManualDue(e.target.value)} /></Field><Field label="Valor"><Input type="number" value={manualAmount} onChange={e => setManualAmount(Number(e.target.value))} /></Field></div><DialogFooter><Button variant="outline" onClick={() => setManual(false)}>Cancelar</Button><Button onClick={createManual}>Criar cobrança</Button></DialogFooter></DialogContent></Dialog></>;
}

function Tasks({ state, commit }: { state: AppState; commit: Commit }) {
  const [day, setDay] = useState("Quinta"), [nature, setNature] = useState("Todas"); const [editing, setEditing] = useState<Task | null>(null); const shown = state.tasks.filter(t => t.days.includes(day) && (nature === "Todas" || t.nature === nature)), done = shown.filter(t => t.completed).length; const blank: Task = { id: "", title: "", category: "Notas Fiscais", nature: "Execução", days: [day], responsible: "Willians", time: "08:00", priority: "Média", notes: "", subitems: [], completed: false };
  function save() { if (!editing?.title.trim()) return toast.error("Informe o nome"); const item = { ...editing, id: editing.id || uid("tarefa") }; commit(`${editing.id ? "Editou" : "Criou"} ${item.title}`, d => { const i = d.tasks.findIndex(t => t.id === item.id); if (i >= 0) d.tasks[i] = item; else d.tasks.unshift(item); }); setEditing(null); toast.success("Tarefa salva"); }
  return <><PageTitle eyebrow="Checklist diário" title="Tarefas de Willians e equipe" description="Recorrências flexíveis, naturezas obrigatórias, subitens e tarefas avulsas." actions={<Button onClick={() => setEditing(blank)}><Plus /> Nova tarefa</Button>} /><div className="day-strip">{dayNames.map(name => <button key={name} className={day === name ? "active" : ""} onClick={() => setDay(name)}><span>{name.slice(0, 3)}</span><strong>{state.tasks.filter(t => t.days.includes(name)).length}</strong></button>)}</div><div className="task-layout"><Card><CardHeader><div className="row"><div><CardTitle>{day}</CardTitle><CardDescription>{done} de {shown.length} concluídas</CardDescription></div><NativeSelect value={nature} onChange={e => setNature(e.target.value)}><NativeSelectOption>Todas</NativeSelectOption>{["Emissão", "Verificação", "Execução", "Lembrete"].map(x => <NativeSelectOption key={x}>{x}</NativeSelectOption>)}</NativeSelect></div><Progress value={shown.length ? done / shown.length * 100 : 0} /></CardHeader><CardContent className="task-list">{shown.map(task => <article key={task.id} className={task.completed ? "done" : ""}><Checkbox checked={task.completed} onCheckedChange={v => commit(`${v ? "Concluiu" : "Reabriu"} ${task.title}`, d => { const x = d.tasks.find(t => t.id === task.id); if (x) x.completed = Boolean(v); })} /><div className={`nature nature-${task.nature.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "")}`}>{task.nature.slice(0, 1)}</div><div className="task-copy"><div><strong>{task.title}</strong><Status>{task.priority}</Status></div><p>{task.notes}</p>{task.subitems.length > 0 && <div className="chips">{task.subitems.map(x => <span key={x}>{x}</span>)}</div>}<small><Clock3 /> {task.time} · {task.responsible} · {task.days.join(", ")}</small></div><div className="task-actions"><Button variant="ghost" size="icon" onClick={() => { commit(`Duplicou ${task.title}`, d => d.tasks.unshift({ ...task, id: uid("tarefa"), title: `${task.title} (cópia)`, completed: false })); toast.success("Duplicada"); }}><Copy /></Button><Button variant="ghost" size="icon" onClick={() => setEditing({ ...task })}><Pencil /></Button></div></article>)}</CardContent></Card><aside className="task-aside"><Card><CardHeader><CardTitle>Legenda</CardTitle></CardHeader><CardContent className="legend">{[["E", "Emissão", "Gera item no Financeiro"], ["V", "Verificação", "Exige OK ou divergente"], ["X", "Execução", "Ação operacional"], ["L", "Lembrete", "Notificação no horário"]].map(([a, b, c]) => <div key={b}><i>{a}</i><span><strong>{b}</strong><small>{c}</small></span></div>)}</CardContent></Card><Card className="note-card"><CardHeader><CardTitle>Recados importantes</CardTitle></CardHeader><CardContent><p>Conferir planilhas, pedidos com alteração e quadro de OK antes dos cadastros.</p><Button variant="outline" onClick={() => setEditing({ ...blank, title: "Conferência de entregas", category: "Conferência", nature: "Verificação", priority: "Alta", notes: "Conferir pedidos com alterações usando planilhas e quadro de OK." })}><Plus /> Transformar em tarefa</Button></CardContent></Card></aside></div><Dialog open={Boolean(editing)} onOpenChange={o => !o && setEditing(null)}><DialogContent className="dialog-wide">{editing && <><DialogHeader><DialogTitle>{editing.id ? "Editar tarefa" : "Nova tarefa"}</DialogTitle><DialogDescription>A natureza define o comportamento da tarefa.</DialogDescription></DialogHeader><div className="form-grid"><Field label="Nome" full><Input value={editing.title} onChange={e => setEditing({ ...editing, title: e.target.value })} /></Field><Field label="Categoria"><Input value={editing.category} onChange={e => setEditing({ ...editing, category: e.target.value })} /></Field><Field label="Natureza"><NativeSelect value={editing.nature} onChange={e => setEditing({ ...editing, nature: e.target.value as TaskNature })}>{["Emissão", "Verificação", "Execução", "Lembrete"].map(x => <NativeSelectOption key={x}>{x}</NativeSelectOption>)}</NativeSelect></Field><Field label="Responsável"><NativeSelect value={editing.responsible} onChange={e => setEditing({ ...editing, responsible: e.target.value })}>{state.settings.users.map(x => <NativeSelectOption key={x.name}>{x.name}</NativeSelectOption>)}</NativeSelect></Field><Field label="Horário"><Input type="time" value={editing.time} onChange={e => setEditing({ ...editing, time: e.target.value })} /></Field><Field label="Prioridade"><NativeSelect value={editing.priority} onChange={e => setEditing({ ...editing, priority: e.target.value as Task["priority"] })}>{["Alta", "Média", "Baixa"].map(x => <NativeSelectOption key={x}>{x}</NativeSelectOption>)}</NativeSelect></Field><Field label="Dias" full><div className="weekday-picker">{dayNames.map(name => <label key={name}><Checkbox checked={editing.days.includes(name)} onCheckedChange={v => setEditing({ ...editing, days: v ? [...editing.days, name] : editing.days.filter(x => x !== name) })} /> {name}</label>)}</div></Field><Field label="Subitens (um por linha)" full><Textarea value={editing.subitems.join("\n")} onChange={e => setEditing({ ...editing, subitems: e.target.value.split("\n").filter(Boolean) })} /></Field><Field label="Observações" full><Textarea value={editing.notes} onChange={e => setEditing({ ...editing, notes: e.target.value })} /></Field></div><DialogFooter><Button variant="outline" onClick={() => setEditing(null)}>Cancelar</Button><Button onClick={save}>Salvar</Button></DialogFooter></>}</DialogContent></Dialog></>;
}

function Routes({ state, commit }: { state: AppState; commit: Commit }) {
  const [base, setBase] = useState("dias-uteis"), [driver, setDriver] = useState("Todos"), [search, setSearch] = useState(""), [page, setPage] = useState(0), [adding, setAdding] = useState(false); const [newRoute, setNewRoute] = useState({ driver: "Retirado", time: "03:00", client: "", french: "", milk: "", notes: "", rule: "programado" as RouteRecord["rule"] }); const baseRows = state.routes.filter(r => r.base === base), drivers = [...new Set(baseRows.map(r => r.driver))], filtered = baseRows.filter(r => (driver === "Todos" || r.driver === driver) && [r.client, r.notes].join(" ").toLowerCase().includes(search.toLowerCase())), rows = filtered.slice(page * 25, page * 25 + 25), registered = baseRows.filter(r => r.registered).length, checked = baseRows.filter(r => r.checked).length;
  useEffect(() => setPage(0), [base, driver, search]); function toggle(id: string, field: "registered" | "checked", value: boolean) { commit(`${value ? "Marcou" : "Desmarcou"} rota`, d => { const x = d.routes.find(r => r.id === id); if (x) { x[field] = value; if (field === "registered" && !value) x.checked = false; if (field === "checked" && value) x.registered = true; } }); } function publish() { const missing = baseRows.filter(r => !r.time || !r.client || !r.driver); if (missing.length) return toast.error(`${missing.length} registros incompletos`); const pending = baseRows.filter(r => !r.checked).length; if (pending) return toast.warning(`${pending} registros sem conferência`); toast.success("Base publicada e versão oficial criada"); }
  return <><PageTitle eyebrow="Planejamento mensal" title="Base de rotas e pedidos" description="As 685 linhas das planilhas foram estruturadas por entregador, horário, regra e conferência." actions={<><Button variant="outline" onClick={() => setAdding(true)}><Plus /> Nova parada</Button><Button onClick={publish}><PackageCheck /> Publicar base</Button></>} /><div className="route-tabs">{[["dias-uteis", "Dias úteis"], ["sabado", "Sábado"], ["domingo", "Domingo"]].map(([id, label]) => <button key={id} onClick={() => { setBase(id); setDriver("Todos"); }} className={base === id ? "active" : ""}><span>{label}</span><strong>{state.routes.filter(r => r.base === id).length}</strong></button>)}</div><div className="route-progress"><div><span><strong>{registered}</strong> cadastrados</span><span><strong>{checked}</strong> conferidos</span><span><strong>{baseRows.filter(r => r.rule === "sob-demanda").length}</strong> sob demanda</span></div><Progress value={checked / baseRows.length * 100} /><small>Publicação bloqueada enquanto houver campos obrigatórios vazios ou itens sem conferência.</small></div><Card><CardHeader><div className="toolbar"><div className="searchbox"><Search /><Input placeholder="Cliente ou observação" value={search} onChange={e => setSearch(e.target.value)} /></div><NativeSelect value={driver} onChange={e => setDriver(e.target.value)}><NativeSelectOption>Todos</NativeSelectOption>{drivers.map(x => <NativeSelectOption key={x}>{x}</NativeSelectOption>)}</NativeSelect><span className="result-count">{filtered.length} paradas</span></div></CardHeader><CardContent className="table-shell"><Table><TableHeader><TableRow><TableHead>Horário</TableHead><TableHead>Entregador / Viagem</TableHead><TableHead>Cliente</TableHead><TableHead>Francês</TableHead><TableHead>Leite</TableHead><TableHead>Regra e observações</TableHead><TableHead>Cadastrado</TableHead><TableHead>Conferido</TableHead></TableRow></TableHeader><TableBody>{rows.map(r => <TableRow key={r.id}><TableCell><strong>{r.time}</strong></TableCell><TableCell>{r.driver}<small className="cell-note">{r.batch}</small></TableCell><TableCell><strong>{r.client}</strong></TableCell><TableCell>{r.french || "-"}</TableCell><TableCell>{r.milk || "-"}</TableCell><TableCell><Status>{r.rule === "sob-demanda" ? "Sob demanda" : r.rule === "fixo" ? "Fixo" : "Programado"}</Status><small className="route-note">{r.notes}</small></TableCell><TableCell><Checkbox checked={r.registered} onCheckedChange={v => toggle(r.id, "registered", Boolean(v))} /></TableCell><TableCell><Checkbox checked={r.checked} onCheckedChange={v => toggle(r.id, "checked", Boolean(v))} /></TableCell></TableRow>)}</TableBody></Table><div className="pagination"><Button variant="outline" size="sm" disabled={!page} onClick={() => setPage(p => p - 1)}><ChevronLeft /> Anterior</Button><span>Página {page + 1} de {Math.max(1, Math.ceil(filtered.length / 25))}</span><Button variant="outline" size="sm" disabled={(page + 1) * 25 >= filtered.length} onClick={() => setPage(p => p + 1)}>Próxima <ChevronRight /></Button></div></CardContent></Card><Dialog open={adding} onOpenChange={setAdding}><DialogContent><DialogHeader><DialogTitle>Nova parada</DialogTitle><DialogDescription>Adicione uma exceção ou novo cliente.</DialogDescription></DialogHeader><div className="stack"><Field label="Entregador"><NativeSelect value={newRoute.driver} onChange={e => setNewRoute({ ...newRoute, driver: e.target.value })}>{drivers.map(x => <NativeSelectOption key={x}>{x}</NativeSelectOption>)}</NativeSelect></Field><Field label="Horário"><Input type="time" value={newRoute.time} onChange={e => setNewRoute({ ...newRoute, time: e.target.value })} /></Field><Field label="Cliente"><Input value={newRoute.client} onChange={e => setNewRoute({ ...newRoute, client: e.target.value })} /></Field><div className="inline"><Field label="Francês"><Input value={newRoute.french} onChange={e => setNewRoute({ ...newRoute, french: e.target.value })} /></Field><Field label="Leite"><Input value={newRoute.milk} onChange={e => setNewRoute({ ...newRoute, milk: e.target.value })} /></Field></div><Field label="Regra"><NativeSelect value={newRoute.rule} onChange={e => setNewRoute({ ...newRoute, rule: e.target.value as RouteRecord["rule"] })}><NativeSelectOption value="fixo">Fixo</NativeSelectOption><NativeSelectOption value="programado">Programado</NativeSelectOption><NativeSelectOption value="sob-demanda">Sob demanda</NativeSelectOption></NativeSelect></Field><Field label="Observações"><Textarea value={newRoute.notes} onChange={e => setNewRoute({ ...newRoute, notes: e.target.value })} /></Field></div><DialogFooter><Button variant="outline" onClick={() => setAdding(false)}>Cancelar</Button><Button onClick={() => { if (!newRoute.client) return toast.error("Informe o cliente"); commit(`Adicionou ${newRoute.client} à rota`, d => d.routes.unshift({ id: uid("rota"), base, source: "Cadastro manual", driver: newRoute.driver, batch: "1ª entrega", time: newRoute.time, client: newRoute.client, french: newRoute.french, milk: newRoute.milk, notes: newRoute.notes, rule: newRoute.rule, registered: false, checked: false })); setAdding(false); }}>Adicionar</Button></DialogFooter></DialogContent></Dialog></>;
}

function Documents({ state, commit }: { state: AppState; commit: Commit }) {
  const [open, setOpen] = useState(false), [type, setType] = useState("Cotação"), [company, setCompany] = useState(state.settings.companies[0].name), [client, setClient] = useState("SESI Taubaté"), [date, setDate] = useState(today), [invoice, setInvoice] = useState("38.754"), [amount, setAmount] = useState(300), [items, setItems] = useState([{ description: "Lanche de Metro Salpicão de Frango", qty: 2, unit: "Und", price: 90 }]), [preview, setPreview] = useState(false); const companyData = state.settings.companies.find(c => c.name === company) ?? state.settings.companies[0], total = items.reduce((s, i) => s + i.qty * i.price, 0);
  function generate() { commit(`Gerou ${type} para ${client}`, d => d.documents.unshift({ id: uid("doc"), type, company, client, date, total: type === "Declaração Bancária" ? amount : total, status: "Gerado" })); setPreview(true); toast.success("Documento salvo no histórico"); }
  return <><PageTitle eyebrow="Modelos corporativos" title="Documentos" description="Cotações, comprovantes e declarações com identidade e assinaturas configuráveis." actions={<Button onClick={() => setOpen(true)}><Plus /> Gerar documento</Button>} /><div className="template-grid">{[{ title: "Cotação / Proposta", icon: FilePenLine, desc: "Itens, valores, validade e pagamento." }, { title: "Comprovante de Entrega", icon: PackageCheck, desc: "Local, data e itens entregues." }, { title: "Declaração Bancária", icon: Building2, desc: "NF, valor, banco, carimbo e assinatura." }].map(t => <Card key={t.title} className="template-card"><CardContent><t.icon /><div><strong>{t.title}</strong><p>{t.desc}</p><Button variant="outline" size="sm" onClick={() => { setType(t.title === "Cotação / Proposta" ? "Cotação" : t.title); setOpen(true); }}>Usar modelo</Button></div></CardContent></Card>)}</div><Card><CardHeader><CardTitle>Histórico</CardTitle><CardDescription>Versões geradas e prontas para reimpressão.</CardDescription></CardHeader><CardContent className="table-shell"><Table><TableHeader><TableRow><TableHead>Documento</TableHead><TableHead>Empresa</TableHead><TableHead>Cliente</TableHead><TableHead>Data</TableHead><TableHead>Valor</TableHead><TableHead>Status</TableHead><TableHead className="right">Ações</TableHead></TableRow></TableHeader><TableBody>{state.documents.map(d => <TableRow key={d.id}><TableCell><strong>{d.type}</strong><small className="cell-note">{d.id}</small></TableCell><TableCell>{d.company.replace("Indústria de Pães ", "")}</TableCell><TableCell>{d.client}</TableCell><TableCell>{dateBR(d.date)}</TableCell><TableCell>{d.total ? money.format(d.total) : "-"}</TableCell><TableCell><Status>{d.status}</Status></TableCell><TableCell className="right"><Button variant="ghost" size="icon" onClick={() => window.print()}><Printer /></Button><Button variant="ghost" size="icon" onClick={() => commit(`Duplicou ${d.type}`, x => x.documents.unshift({ ...d, id: uid("doc"), date: today, status: "Rascunho" }))}><Copy /></Button></TableCell></TableRow>)}</TableBody></Table></CardContent></Card><Dialog open={open} onOpenChange={setOpen}><DialogContent className="dialog-xl"><DialogHeader><DialogTitle>Gerar documento</DialogTitle><DialogDescription>Logo, dados, cores e assinatura mudam conforme a empresa.</DialogDescription></DialogHeader><div className="document-builder"><div className="document-form"><Field label="Tipo"><NativeSelect value={type} onChange={e => setType(e.target.value)}><NativeSelectOption>Cotação</NativeSelectOption><NativeSelectOption>Comprovante de Entrega</NativeSelectOption><NativeSelectOption>Declaração Bancária</NativeSelectOption></NativeSelect></Field><Field label="Empresa"><NativeSelect value={company} onChange={e => setCompany(e.target.value)}>{state.settings.companies.map(c => <NativeSelectOption key={c.name}>{c.name}</NativeSelectOption>)}</NativeSelect></Field><Field label="Cliente / destinatário"><Input value={client} onChange={e => setClient(e.target.value)} /></Field><Field label="Data"><Input type="date" value={date} onChange={e => setDate(e.target.value)} /></Field>{type === "Declaração Bancária" ? <><Field label="NF"><Input value={invoice} onChange={e => setInvoice(e.target.value)} /></Field><Field label="Valor"><Input type="number" value={amount} onChange={e => setAmount(Number(e.target.value))} /></Field></> : <><Label>Itens</Label>{items.map((item, i) => <div className="item-editor" key={i}><Input value={item.description} onChange={e => setItems(items.map((x, j) => j === i ? { ...x, description: e.target.value } : x))} /><Input type="number" value={item.qty} onChange={e => setItems(items.map((x, j) => j === i ? { ...x, qty: Number(e.target.value) } : x))} /><Input type="number" value={item.price} onChange={e => setItems(items.map((x, j) => j === i ? { ...x, price: Number(e.target.value) } : x))} /><Button variant="ghost" size="icon" onClick={() => setItems(items.filter((_, j) => j !== i))}><X /></Button></div>)}<Button variant="outline" size="sm" onClick={() => setItems([...items, { description: "", qty: 1, unit: "Und", price: 0 }])}><Plus /> Adicionar item</Button></>}</div><DocumentPaper type={type} company={companyData} client={client} date={date} invoice={invoice} amount={amount} items={items} /></div><DialogFooter><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button onClick={generate}><Printer /> Gerar e salvar</Button></DialogFooter></DialogContent></Dialog><Dialog open={preview} onOpenChange={setPreview}><DialogContent className="dialog-xl"><DialogHeader><DialogTitle>Documento pronto</DialogTitle><DialogDescription>Use a impressão do navegador para salvar em PDF A4.</DialogDescription></DialogHeader><DocumentPaper type={type} company={companyData} client={client} date={date} invoice={invoice} amount={amount} items={items} print /><DialogFooter><Button variant="outline" onClick={() => setPreview(false)}>Fechar</Button><Button onClick={() => window.print()}><Printer /> Imprimir / Salvar PDF</Button></DialogFooter></DialogContent></Dialog></>;
}
function DocumentPaper({ type, company, client, date, invoice, amount, items, print = false }: { type: string; company: AppState["settings"]["companies"][number]; client: string; date: string; invoice: string; amount: number; items: { description: string; qty: number; unit: string; price: number }[]; print?: boolean }) { const total = items.reduce((s, i) => s + i.qty * i.price, 0), nova = company.name.includes("Nova"); return <article className={`paper ${print ? "print-area" : ""}`} style={{ ["--paper-accent" as string]: company.primary }}><img className="paper-logo" src={company.logo} alt={company.name} />{type === "Cotação" && <><p className="recipient">A/C<br /><strong>{client.toUpperCase()}</strong></p><p>A empresa <strong>{company.name}</strong>, inscrita no CNPJ {company.document}, com sede em {company.address}, apresenta sua proposta comercial.</p><table><thead><tr><th>Item</th><th>Descrição</th><th>QTD</th><th>Unitário</th><th>Total</th></tr></thead><tbody>{items.map((item, i) => <tr key={i}><td>{i + 1}</td><td>{item.description}</td><td>{item.qty}</td><td>{money.format(item.price)}</td><td>{money.format(item.qty * item.price)}</td></tr>)}</tbody></table><strong className="paper-total">Valor total: {money.format(total)}</strong><p>Os valores incluem custos operacionais, transporte e encargos incidentes no fornecimento.</p><p><strong>Validade:</strong> 90 dias<br /><strong>Pagamento:</strong> 30 dias</p></>}{type === "Comprovante de Entrega" && <><h2>COMPROVANTE DE ENTREGA</h2><p><strong>Local de entrega:</strong> {client}</p><p><strong>Data de entrega:</strong> {dateBR(date)}</p><table><thead><tr><th>Qtd</th><th>Und</th><th>Itens</th></tr></thead><tbody>{items.map((item, i) => <tr key={i}><td>{item.qty}</td><td>{item.unit}</td><td>{item.description}</td></tr>)}</tbody></table></>}{type === "Declaração Bancária" && <><h2>DECLARAÇÃO DE DADOS BANCÁRIOS</h2><p>Referente à <strong>Nota Fiscal Nº {invoice}</strong>, declaramos que receberemos de <strong>{client}</strong> o valor de <strong>{money.format(amount)}</strong>.</p><p>Por meio de crédito bancário na conta abaixo:</p><div className="bank-data"><span>Banco: <strong>Banco Bradesco</strong></span><span>Agência: <strong>Nº 0225</strong></span><span>Conta: <strong>Nº 27240-0</strong></span><span>Favorecido: <strong>{nova ? "Pereira Martins Panificadora Industrial LTDA" : company.name}</strong></span><span>CNPJ: <strong>{company.document}</strong></span></div></>}<div className="paper-sign"><span>São José dos Campos, {dateBR(date)}.</span><p>Atenciosamente,</p><img src={nova ? "/brand/assinatura-yerardo.png" : "/brand/assinatura-excelencia.png"} alt="Assinatura" /><strong>{nova ? "Yerardo Vargas" : company.name}</strong></div><footer>{company.name} · CNPJ {company.document}<br />{company.address}<br />{company.phone} · {company.email}</footer></article>; }

function Notices({ state, commit, user }: { state: AppState; commit: Commit; user: string }) { const [text, setText] = useState(""), [recipient, setRecipient] = useState("Willians"), [priority, setPriority] = useState<"Alta" | "Média" | "Baixa">("Média"), [createTask, setCreateTask] = useState(false); function add() { if (!text.trim()) return toast.error("Escreva o recado"); commit("Criou recado", d => { d.notices.unshift({ id: uid("recado"), text, sender: user, recipients: [recipient], priority, status: "Pendente", createdAt: new Date().toISOString(), createTask }); if (createTask) d.tasks.unshift({ id: uid("tarefa"), title: text.slice(0, 80), category: "Recado", nature: "Lembrete", days: ["Quarta"], responsible: recipient, time: "08:00", priority, notes: text, subitems: [], completed: false }); }); setText(""); toast.success(createTask ? "Recado e tarefa criados" : "Recado enviado"); } return <><PageTitle eyebrow="Comunicação interna" title="Recados" description="Mensagens gerais ou vinculadas a clientes, cobranças e fechamentos." /><div className="messages-grid"><Card><CardHeader><CardTitle>Novo recado</CardTitle><CardDescription>O destinatário será avisado.</CardDescription></CardHeader><CardContent className="stack"><Field label="Mensagem"><Textarea rows={6} value={text} onChange={e => setText(e.target.value)} /></Field><Field label="Destinatário"><NativeSelect value={recipient} onChange={e => setRecipient(e.target.value)}>{state.settings.users.map(x => <NativeSelectOption key={x.name}>{x.name}</NativeSelectOption>)}</NativeSelect></Field><Field label="Prioridade"><NativeSelect value={priority} onChange={e => setPriority(e.target.value as typeof priority)}>{["Alta", "Média", "Baixa"].map(x => <NativeSelectOption key={x}>{x}</NativeSelectOption>)}</NativeSelect></Field><label className="switch-row"><Switch checked={createTask} onCheckedChange={setCreateTask} /><span><strong>Gerar tarefa</strong><small>Cria lembrete para o destinatário</small></span></label><Button onClick={add}><MessageSquareText /> Enviar recado</Button></CardContent></Card><Card><CardHeader><CardTitle>Caixa de entrada</CardTitle><CardDescription>{state.notices.filter(n => n.status === "Pendente").length} pendentes</CardDescription></CardHeader><CardContent className="notice-list">{state.notices.map(n => <article key={n.id}><div className="notice-avatar">{n.sender.slice(0, 1)}</div><div><div><strong>{n.sender}</strong><Status>{n.priority}</Status></div><p>{n.text}</p><small>Para {n.recipients.join(", ")} · {dateBR(n.createdAt)}</small></div><Button variant="ghost" size="sm" onClick={() => commit(`Concluiu recado de ${n.sender}`, d => { const x = d.notices.find(y => y.id === n.id); if (x) x.status = x.status === "Concluído" ? "Pendente" : "Concluído"; })}>{n.status === "Concluído" ? <RotateCcw /> : <Check />}</Button></article>)}</CardContent></Card></div></>; }

function Reports({ state }: { state: AppState }) { const paid = state.collections.filter(c => ["Paga", "Baixada"].includes(c.status)).reduce((a, c) => a + c.amount, 0), overdue = state.collections.filter(c => c.dueDate < today && !["Paga", "Baixada", "Arquivada"].includes(c.status)).reduce((a, c) => a + c.amount, 0), statuses = ["Pendente", "Em andamento", "Reagendada", "Paga", "Cancelamento pendente"].map(name => ({ name, count: state.collections.filter(c => c.status === name).length })), max = Math.max(...statuses.map(x => x.count), 1); return <><PageTitle eyebrow="Indicadores gerenciais" title="Relatórios" description="Visões para supervisão financeira, operacional e diretoria." actions={<Button variant="outline" onClick={() => window.print()}><Printer /> Imprimir</Button>} /><div className="metrics-grid compact"><Metric label="Recebido" value={money.format(paid)} detail="pagamentos registrados" icon={CheckCircle2} tone="green" /><Metric label="Vencido" value={money.format(overdue)} detail="saldo em atraso" icon={TriangleAlert} tone="red" /><Metric label="Conclusão" value={`${Math.round(state.tasks.filter(t => t.completed).length / state.tasks.length * 100)}%`} detail="tarefas recorrentes" icon={ClipboardCheck} tone="blue" /><Metric label="Clientes ativos" value={state.clients.filter(c => c.active).length} detail="base unificada" icon={UsersRound} /></div><div className="reports-grid"><Card><CardHeader><CardTitle>Cobranças por status</CardTitle></CardHeader><CardContent className="bars">{statuses.map(s => <div key={s.name}><span>{s.name}</span><div><i style={{ width: `${s.count / max * 100}%` }} /></div><strong>{s.count}</strong></div>)}</CardContent></Card><Card><CardHeader><CardTitle>Inadimplência por cliente</CardTitle></CardHeader><CardContent className="ranking">{state.clients.map(c => ({ c, amount: state.collections.filter(x => x.clientId === c.id && !["Paga", "Baixada", "Arquivada"].includes(x.status)).reduce((a, x) => a + x.amount, 0) })).filter(x => x.amount).sort((a, b) => b.amount - a.amount).map((x, i) => <div key={x.c.id}><em>{i + 1}</em><span><strong>{x.c.name}</strong><small>{x.c.priority} · {x.c.collectors.join(", ")}</small></span><strong>{money.format(x.amount)}</strong></div>)}</CardContent></Card><Card className="span-2"><CardHeader><CardTitle>Performance da operação</CardTitle></CardHeader><CardContent><Table><TableHeader><TableRow><TableHead>Responsável</TableHead><TableHead>Emissões</TableHead><TableHead>Cobranças</TableHead><TableHead>Tarefas</TableHead><TableHead>Índice</TableHead></TableRow></TableHeader><TableBody>{["Yerardo", "Natanael", "Willians"].map(name => { const a = state.emissions.filter(e => e.responsible === name).length, b = state.collections.filter(c => c.responsible === name).length, c = state.tasks.filter(t => t.responsible === name).length; return <TableRow key={name}><TableCell><strong>{name}</strong></TableCell><TableCell>{a}</TableCell><TableCell>{b}</TableCell><TableCell>{c}</TableCell><TableCell><Progress value={Math.min(100, (a + b + c) * 7)} /></TableCell></TableRow>; })}</TableBody></Table></CardContent></Card></div></>; }

function FinancialConfiguration({ state, commit }: { state: AppState; commit: Commit }) {
  const [tab, setTab] = useState("regras");
  const [newValue, setNewValue] = useState("");
  function backup() { const blob = new Blob([JSON.stringify(state, null, 2)], { type: "application/json" }), url = URL.createObjectURL(blob), anchor = document.createElement("a"); anchor.href = url; anchor.download = `BACKUP_GESTAO_${today}.json`; anchor.click(); URL.revokeObjectURL(url); toast.success("Backup gerado"); }
  function restore(file?: File) { if (!file) return; const reader = new FileReader(); reader.onload = () => { try { const data = normalizeFinancialState(JSON.parse(String(reader.result))); commit("Restaurou backup", draft => Object.assign(draft, data)); toast.success("Backup restaurado"); } catch { toast.error("Backup inválido"); } }; reader.readAsText(file); }
  return <><PageTitle eyebrow="Administração financeira" title="Configurações" description="Crie e edite fechamentos, vencimentos, políticas por cor e grupos usando seletores." /><Tabs value={tab} onValueChange={setTab}><TabsList className="settings-tabs"><TabsTrigger value="regras">Regras financeiras</TabsTrigger><TabsTrigger value="empresas">Empresas</TabsTrigger><TabsTrigger value="usuarios">Usuários e perfis</TabsTrigger><TabsTrigger value="listas">Formas e listas</TabsTrigger><TabsTrigger value="backup">Backup e auditoria</TabsTrigger></TabsList>
    <TabsContent value="regras"><FinancialRuleSettings state={state} commit={commit} /></TabsContent>
    <TabsContent value="empresas"><div className="settings-cards">{state.settings.companies.map(company => <Card key={company.name}><CardContent className="company-card"><img src={company.logo} alt={company.name} /><div><strong>{company.name}</strong><small>{company.document}</small><span>{company.email}<br />{company.phone}</span></div><input type="color" value={company.primary} aria-label={`Cor de ${company.name}`} onChange={event => commit(`Alterou cor de ${company.name}`, draft => { const current = draft.settings.companies.find(item => item.name === company.name); if (current) current.primary = event.target.value; })} /></CardContent></Card>)}</div></TabsContent>
    <TabsContent value="usuarios"><Card><CardHeader><CardTitle>Usuários e perfis</CardTitle><CardDescription>O cliente pode ser vinculado ao responsável pela emissão e aos cobradores.</CardDescription></CardHeader><CardContent className="table-shell"><Table><TableHeader><TableRow><TableHead>Usuário</TableHead><TableHead>E-mail</TableHead><TableHead>Perfil</TableHead><TableHead>Ativo</TableHead></TableRow></TableHeader><TableBody>{state.settings.users.map(account => <TableRow key={account.email}><TableCell><strong>{account.name}</strong></TableCell><TableCell>{account.email}</TableCell><TableCell>{account.role}</TableCell><TableCell><Switch checked={account.active} onCheckedChange={value => commit(`${value ? "Ativou" : "Desativou"} ${account.name}`, draft => { const current = draft.settings.users.find(item => item.email === account.email); if (current) current.active = value; })} /></TableCell></TableRow>)}</TableBody></Table></CardContent></Card></TabsContent>
    <TabsContent value="listas"><div className="settings-columns"><Card><CardHeader><CardTitle>Formas de pagamento</CardTitle></CardHeader><CardContent className="stack"><div className="inline"><Input value={newValue} onChange={event => setNewValue(event.target.value)} placeholder="Nova forma de pagamento" /><Button onClick={() => { if (!newValue.trim()) return; commit(`Adicionou ${newValue}`, draft => draft.settings.paymentMethods.push(newValue.trim())); setNewValue(""); }}><Plus /></Button></div><div className="chips">{state.settings.paymentMethods.map(item => <span key={item}>{item}</span>)}</div></CardContent></Card><Card><CardHeader><CardTitle>Datas já automatizadas</CardTitle></CardHeader><CardContent className="stack"><p>Diário, segundas, quarta de congelados, sextas, quinzenal, dias 20/25 e mensal no primeiro dia do mês seguinte.</p><Button variant="outline" onClick={() => setTab("regras")}><CalendarDays /> Gerenciar regras</Button></CardContent></Card></div></TabsContent>
    <TabsContent value="backup"><div className="settings-columns"><Card><CardHeader><CardTitle>Backup</CardTitle></CardHeader><CardContent className="stack"><Button onClick={backup}><Download /> Baixar backup completo</Button><Label className="upload-button"><Upload /> Restaurar backup<Input type="file" accept=".json" onChange={event => restore(event.target.files?.[0])} /></Label><small>A restauração substitui o estado atual e aplica a migração das regras financeiras.</small></CardContent></Card><Card><CardHeader><CardTitle>Auditoria recente</CardTitle></CardHeader><CardContent className="audit-list">{state.audit.slice(0, 12).map((item, index) => <div key={index}><History /><span><strong>{item.user}</strong><small>{item.action}</small></span><time>{dateBR(item.at)}</time></div>)}</CardContent></Card></div></TabsContent>
  </Tabs></>;
}

// Mantido apenas para compatibilidade de versões antigas do estado.
// eslint-disable-next-line @typescript-eslint/no-unused-vars
function Configuration({ state, commit }: { state: AppState; commit: Commit }) { const [tab, setTab] = useState("empresas"), [newValue, setNewValue] = useState(""); function backup() { const blob = new Blob([JSON.stringify(state, null, 2)], { type: "application/json" }), url = URL.createObjectURL(blob), a = document.createElement("a"); a.href = url; a.download = `BACKUP_GESTAO_${today}.json`; a.click(); URL.revokeObjectURL(url); toast.success("Backup gerado"); } function restore(file?: File) { if (!file) return; const r = new FileReader(); r.onload = () => { try { const data = JSON.parse(String(r.result)); commit("Restaurou backup", d => Object.assign(d, data)); toast.success("Backup restaurado"); } catch { toast.error("Backup inválido"); } }; r.readAsText(file); } return <><PageTitle eyebrow="Administração" title="Configurações" description="Empresas, perfis, regras, campos, identidade, calendário e backups sem alterar código." /><Tabs value={tab} onValueChange={setTab}><TabsList className="settings-tabs"><TabsTrigger value="empresas">Empresas</TabsTrigger><TabsTrigger value="usuarios">Usuários e perfis</TabsTrigger><TabsTrigger value="regras">Regras</TabsTrigger><TabsTrigger value="campos">Campos</TabsTrigger><TabsTrigger value="feriados">Feriados</TabsTrigger><TabsTrigger value="backup">Backup e auditoria</TabsTrigger></TabsList><TabsContent value="empresas"><div className="settings-cards">{state.settings.companies.map(c => <Card key={c.name}><CardContent className="company-card"><img src={c.logo} alt={c.name} /><div><strong>{c.name}</strong><small>{c.document}</small><span>{c.email}<br />{c.phone}</span></div><input type="color" value={c.primary} aria-label="Cor" onChange={e => commit(`Alterou cor de ${c.name}`, d => { const x = d.settings.companies.find(y => y.name === c.name); if (x) x.primary = e.target.value; })} /></CardContent></Card>)}</div></TabsContent><TabsContent value="usuarios"><Card><CardHeader><CardTitle>Usuários e perfis</CardTitle><CardDescription>Permissões por recurso e ação.</CardDescription></CardHeader><CardContent className="table-shell"><Table><TableHeader><TableRow><TableHead>Usuário</TableHead><TableHead>E-mail</TableHead><TableHead>Perfil</TableHead><TableHead>Permissões</TableHead><TableHead>Ativo</TableHead></TableRow></TableHeader><TableBody>{state.settings.users.map(u => <TableRow key={u.email}><TableCell><strong>{u.name}</strong></TableCell><TableCell>{u.email}</TableCell><TableCell>{u.role}</TableCell><TableCell><div className="chips">{(state.settings.profiles.find(p => p.name === u.role)?.permissions ?? ["configurável"]).slice(0, 3).map(x => <span key={x}>{x}</span>)}</div></TableCell><TableCell><Switch checked={u.active} onCheckedChange={v => commit(`${v ? "Ativou" : "Desativou"} ${u.name}`, d => { const x = d.settings.users.find(y => y.email === u.email); if (x) x.active = v; })} /></TableCell></TableRow>)}</TableBody></Table></CardContent></Card></TabsContent><TabsContent value="regras"><div className="settings-columns"><Card><CardHeader><CardTitle>Regras de cobrança</CardTitle></CardHeader><CardContent className="rules-list">{state.settings.colorRules.map(r => <div key={r.name}><input type="color" value={r.color} onChange={e => commit(`Alterou cor ${r.name}`, d => { const x = d.settings.colorRules.find(y => y.name === r.name); if (x) x.color = e.target.value; })} /><span><strong>{r.name}</strong><small>{r.action}</small></span><em>Prioridade {r.priority}</em></div>)}</CardContent></Card><Card><CardHeader><CardTitle>Tabelas de vencimento</CardTitle></CardHeader><CardContent className="rules-list">{state.settings.dueRules.map(r => <div key={r.name}><CalendarDays /><span><strong>{r.name}</strong><small>{r.type} · {r.days} dias · {r.adjustment}</small></span><Button variant="ghost" size="icon"><Pencil /></Button></div>)}</CardContent></Card><Card><CardHeader><CardTitle>Listas rápidas</CardTitle></CardHeader><CardContent className="stack"><div className="inline"><Input value={newValue} onChange={e => setNewValue(e.target.value)} placeholder="Nova forma de pagamento" /><Button onClick={() => { if (!newValue.trim()) return; commit(`Adicionou ${newValue}`, d => d.settings.paymentMethods.push(newValue)); setNewValue(""); }}><Plus /></Button></div><div className="chips">{state.settings.paymentMethods.map(x => <span key={x}>{x}</span>)}</div></CardContent></Card></div></TabsContent><TabsContent value="campos"><Card><CardHeader><CardTitle>Campos personalizados</CardTitle></CardHeader><CardContent><Table><TableHeader><TableRow><TableHead>Entidade</TableHead><TableHead>Rótulo</TableHead><TableHead>Tipo</TableHead><TableHead>Obrigatório</TableHead></TableRow></TableHeader><TableBody>{state.settings.customFields.map((f, i) => <TableRow key={i}><TableCell>{f.entity}</TableCell><TableCell><strong>{f.label}</strong></TableCell><TableCell>{f.type}</TableCell><TableCell><Switch checked={f.required} onCheckedChange={v => commit(`Alterou ${f.label}`, d => { d.settings.customFields[i].required = v; })} /></TableCell></TableRow>)}</TableBody></Table></CardContent></Card></TabsContent><TabsContent value="feriados"><Card><CardHeader><CardTitle>Feriados e regras</CardTitle></CardHeader><CardContent className="holiday-list">{state.settings.holidays.map(h => <div key={h.date}><CalendarDays /><span><strong>{dateBR(h.date)} · {h.name}</strong><small>{h.type} · {h.driverRule}</small></span><Button variant="ghost" size="icon"><Pencil /></Button></div>)}</CardContent></Card></TabsContent><TabsContent value="backup"><div className="settings-columns"><Card><CardHeader><CardTitle>Backup</CardTitle></CardHeader><CardContent className="stack"><Button onClick={backup}><Download /> Baixar backup completo</Button><Label className="upload-button"><Upload /> Restaurar backup<Input type="file" accept=".json" onChange={e => restore(e.target.files?.[0])} /></Label><small>A restauração substitui o estado atual.</small></CardContent></Card><Card><CardHeader><CardTitle>Auditoria recente</CardTitle></CardHeader><CardContent className="audit-list">{state.audit.slice(0, 12).map((a, i) => <div key={i}><History /><span><strong>{a.user}</strong><small>{a.action}</small></span><time>{dateBR(a.at)}</time></div>)}</CardContent></Card></div></TabsContent></Tabs></>; }
